'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const material=read('docs/scifi-ui/scripts/formatx-core-mesh3d-material-v21.js');
const shape=read('docs/scifi-ui/scripts/formatx-core-shape-v14.js');
const geometry=read('docs/scifi-ui/scripts/formatx-core-geometry-v13.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v11.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v11.js');
const grade=read('docs/scifi-ui/styles/formatx-core-cinematic-grade-v21.css');
const kick=read('docs/scifi-ui/scripts/formatx-core-cinematic-kick-v11.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');

assert.match(mapper,/fxApexSceneStability==='ready-v31'/,'v21 mapper revision missing');
assert.match(mapper,/formatx-core-mesh3d-material-v21\.js\?v=20260809-sparse-hdr-facets-v21/,'v21 material bootstrap missing');
assert.match(mapper,/formatx-core-cinematic-grade-v21\.css\?v=20260809-sparse-hdr-v21/,'v21 grade bootstrap missing');
assert.match(mapper,/reference-glass-v21-sparse-high-dynamic-facets/,'v21 material contract missing');
assert.match(mapper,/reference-polygon-contrast-v21/,'v21 calibration contract missing');
assert.match(mapper,/cinematic-sparse-hdr-reference-glass-v31/,'v21 visual marker missing');
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/,'mapper must not capture scrolling');

assert.match(material,/vec2 cp=vec2\(vP\.x,vP\.y-\.18\)/,'object-space center correction missing');
assert.match(material,/float planeGlow=sm\(\.70,\.90,face\)/,'sparse facet threshold missing');
assert.match(material,/planePeak=pow\(face,8\.0\)/,'sparse facet peak missing');
assert.match(material,/webA=.*7\.6/s,'medium webA distribution missing');
assert.match(material,/webB=.*8\.1/s,'medium webB distribution missing');
assert.match(material,/webC=.*8\.6/s,'medium webC distribution missing');
assert.match(material,/float hAxis=exp\(-abs\(cp\.y\)\*19\.0\)/,'narrow horizontal energy axis missing');
assert.match(material,/float ridgeA=/,'diagonal ridge missing');
assert.match(material,/float ringGlow=/,'surface ring glow missing');
assert.match(material,/float highlight=sat\(max/,'sparse highlight coverage mask missing');
assert.match(material,/uAlpha\*\(\.13\*planeGlow\+\.10\*web/,'sparse highlight alpha missing');
assert.match(material,/fxCoreHighlightModel='sparse-high-dynamic-facets-v21'/,'v21 highlight model marker missing');
assert.match(material,/fxCoreHighlightCoverage='thresholded-facet-web-axis-ring-v21'/,'v21 highlight coverage marker missing');
assert.match(material,/fxCoreMeshMaterial='reference-glass-v21'/,'v21 material applied marker missing');
assert.match(material,/fxCoreMeshMaterialPatch='applied-v21'/,'v21 material patch marker missing');
assert.match(material,/fxCoreMaterialCenter='object-space-y-minus-0\.18'/,'material center marker missing');
assert.doesNotMatch(material,/drawImage\s*\(|new Image\s*\(|background-image/i,'MAG material must remain procedural');

assert.match(shape,/aPosition\.y\*\.72/,'reference Y ratio missing');
assert.match(shape,/fxCoreShapeMesh='applied-v14'/,'mesh shape patch missing');
assert.match(shape,/fxCoreShapeFracture='applied-v14'/,'fracture shape patch missing');
assert.match(geometry,/value\*1\.15/,'true 3D scale multiplier missing');
assert.match(geometry,/fxCoreGeometryScale='1\.15x-true-3d-uniform'/,'true 3D scale marker missing');
assert.match(mesh,/getContext\('webgl2'/,'WebGL2 mesh context missing');
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/,'depth testing missing');
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangles missing');
assert.match(mesh,/fxCoreGeometry='indexed-triangle-mesh-v11'/,'indexed mesh marker missing');
assert.match(fracture,/gl\.drawElements\(gl\.LINES/,'indexed fracture lines missing');
assert.match(fracture,/fxCoreFracture3d='ready-v11'/,'fracture marker missing');

assert.match(grade,/brightness\(2\.02\)/,'desktop brightness calibration missing');
assert.match(grade,/saturate\(1\.12\)/,'desktop saturation calibration missing');
assert.match(grade,/opacity: 0\.80/,'desktop fracture strength missing');
assert.match(grade,/brightness\(2\.08\)/,'mobile brightness calibration missing');
assert.match(grade,/saturate\(1\.14\)/,'mobile saturation calibration missing');
assert.match(grade,/opacity: 0\.78/,'mobile fracture strength missing');

assert.match(kick,/formatx:organismresponse.*\.74,1\.15,2100/s,'frame-rate independent response impulse missing');
assert.match(infinite,/const VERSION = 'seamless-v7'/,'seamless-v7 regressed');
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/,'native momentum regressed');
console.log('PASS: v21 keeps the v19-class dark glass body while adding thresholded sparse HDR facets and preserving true WebGL2 geometry and seamless-v7 native scrolling.');
